9:export function parseCommand(value) {
10:  if (typeof value === "object" && value !== null) {
11:    invariant(typeof value.command === "string" && value.command.trim() && Array.isArray(value.args) && value.args.every((arg) => typeof arg === "string"), "INVALID_VERIFICATION_COMMAND", "验证声明需要 command 和字符串 args 数组。" );
