13:  }
14:  invariant(typeof value === "string" && value.trim(), "INVALID_VERIFICATION_COMMAND", "验证必须声明实际命令。" );
15:  if (value.trimStart().startsWith("{")) {
16:    let parsed;
17:    try { parsed = JSON.parse(value); } catch { invariant(false, "INVALID_VERIFICATION_COMMAND", "结构化验证命令不是有效 JSON。" ); }
18:    return parseCommand(parsed);
19:  }
20:  invariant(!/[\r\n]/.test(value), "SHELL_VERIFICATION_UNSUPPORTED", "多行命令需要拆成独立验证声明。" );
21:  const tokens = [];
22:  let token = "";
23:  let quoted = null;
24:  let started = false;
25:  for (let index = 0; index < value.length; index += 1) {
26:    const char = value[index];
27:    if (quoted) {
28:      if (char === quoted) quoted = null;
29:      else if (char === "\\" && value[index + 1] === quoted) token += value[++index];
30:      else token += char;
31:    } else if (char === '"' || char === "'") {
32:      quoted = char;
33:      started = true;
34:    } else if (/\s/.test(char)) {
35:      if (started) tokens.push(token);
36:      token = "";
37:      started = false;
38:    } else {
39:      invariant(!/[;&|<>`]/.test(char) && !(char === "$" && value[index + 1] === "("), "SHELL_VERIFICATION_UNSUPPORTED", "验证命令不能包含 shell 操作符或展开；请提供 command/args JSON。" );
40:      token += char;
41:      started = true;
42:    }
43:  }
44:  invariant(!quoted, "INVALID_VERIFICATION_COMMAND", "验证命令存在未闭合引号。" );
45:  if (started) tokens.push(token);
46:  invariant(tokens[0]?.trim(), "INVALID_VERIFICATION_COMMAND", "验证命令缺少可执行文件。" );
47:  return { command: tokens[0], args: tokens.slice(1) };
48:}
