71:export async function resolveCommandLaunch(command, args, { platform = process.platform, searchPath = process.env.PATH || process.env.Path || "" } = {}) {
72:  if (commandKey(command, []) === commandKey("node", [])) return { command: process.execPath, args: [...args] };
