353:export async function assertTransitionGates(root, item, plan, target) {
354:  if (target === "BLOCKED" || item.status === "BLOCKED") return;
355:  if (target === "BASELINING") {
356:    invariant(nonEmptyStrings(item.input.references), "INPUT_REQUIRED", "工作项至少需要一个权威输入或问题引用。" );
357:    invariant(nonEmptyStrings(item.input.acceptance), "ACCEPTANCE_REQUIRED", "工作项至少需要一个可判定完成条件。" );
358:    if (item.type === "NEW_PROJECT") {
359:      invariant(["HUMAN_PROVIDED", "AI_RECOMMENDED"].includes(item.architecture.source), "ARCHITECTURE_SOURCE_REQUIRED", "新项目必须明确架构来源。" );
360:      invariant(item.architecture.approvalRef?.trim(), "ARCHITECTURE_APPROVAL_REQUIRED", "新项目架构必须提供批准/授权引用。" );
361:    }
362:    if (item.type === "BUGFIX") {
363:      invariant(item.bug?.actual?.trim() && item.bug?.expected?.trim() && item.bug?.reproduction?.trim(), "BUG_BASELINE_REQUIRED", "BUGFIX 必须提供实际行为、期望行为和复现路径。" );
364:    }
365:    return;
366:  }
367:  if (["SOLUTION_DESIGN", "ANALYZING"].includes(target)) {
368:    await assertEvidenceDocument(root, item.baseline, "基线");
369:    invariant(isObject(item.baseline.repository), "REPOSITORY_BASELINE_REQUIRED", "基线缺少仓库状态。" );
370:    return;
371:  }
372:  if (target === "DATABASE_DESIGN") {
373:    await assertEvidenceDocument(root, item.solution, "技术设计", { documentRequired: true });
374:    invariant(item.database.impact === "required", "DATABASE_IMPACT_MISMATCH", "只有数据库影响 required 才能进入 DATABASE_DESIGN。" );
375:    return;
376:  }
377:  if (target === "PLANNED") {
378:    await assertEvidenceDocument(root, item.solution, "技术设计", { documentRequired: true });
379:    invariant(item.database.impact !== "unknown", "DATABASE_DECISION_REQUIRED", "计划前必须完成数据库影响判断。" );
380:    if (item.database.impact === "required") {
381:      await assertEvidenceDocument(root, item.database, "数据库设计", { documentRequired: true });
382:    } else {
383:      await assertEvidenceDocument(root, item.database, "数据库不适用结论");
384:    }
385:    invariant(plan, "PLAN_REQUIRED", "进入 PLANNED 前必须创建执行计划。" );
386:    assertValidPlan(plan, item.id, { requireContent: true });
387:    invariant(item.plan.approved && item.plan.approvalRef?.trim(), "PLAN_APPROVAL_REQUIRED", "计划必须有批准或端到端授权记录。" );
388:    return;
389:  }
390:  if (target === "IMPLEMENTING") {
391:    invariant(plan, "PLAN_REQUIRED", "实现前缺少计划。" );
392:    assertValidPlan(plan, item.id, { requireContent: true });
393:    invariant(item.plan.approved, "PLAN_APPROVAL_REQUIRED", "实现前计划必须批准。" );
394:    return;
395:  }
396:  if (target === "VERIFYING") {
397:    invariant(plan, "PLAN_REQUIRED", "验证前缺少计划。" );
398:    assertValidPlan(plan, item.id, { requireContent: true });
399:    const unfinished = plan.tasks.filter((task) => !["COMPLETED", "DEFERRED"].includes(task.status));
400:    invariant(unfinished.length === 0, "TASKS_UNFINISHED", "仍有任务未完成或未获批准延期。", {
401:      tasks: unfinished.map((task) => `${task.id}:${task.status}`),
402:    });
403:    return;
404:  }
405:  if (target === "CODE_REVIEW") {
406:    if (usesVerificationPipeline(item)) {
407:      const required = requiredVerificationStages(item);
408:      const statusByStage = new Map((item.verification.stages || []).map((stage) => [stage.stage, stage.status]));
409:      const missing = required.filter((name) => statusByStage.get(name) !== "pass");
410:      invariant(missing.length === 0, "VERIFICATION_PIPELINE_INCOMPLETE", `验证流水线未完成，缺少通过阶段：${missing.join(", ")}`, { missing });
411:    }
412:    invariant(item.verification.status === "pass" && nonEmptyStrings(item.verification.evidence), "FINAL_VERIFICATION_REQUIRED", "工作项验证尚未通过。" );
413:    invariant(["pass", "not-applicable"].includes(item.documentation.status) && nonEmptyStrings(item.documentation.evidence), "DOCUMENTATION_REQUIRED", "文档同步尚未确认。" );
414:    if (!(item.status === "DONE" && !item.integrityVersion)) {
415:      const snapshot = item.status === "DONE" ? await loadSnapshot(root, item.delivery?.source) : await sourceSnapshot(root);
416:      await assertVerification(root, item, plan, { snapshot });
417:      await assertVerificationStages(root, item, plan, snapshot);
418:      invariant(item.verification.source?.digest === snapshot.digest, "STALE_VERIFICATION", "验证结论不对应当前待交付代码。" );
419:    }
420:    return;
421:  }
422:  if (target === "READY_FOR_ACCEPTANCE") {
423:    invariant(item.review.status === "pass" && nonEmptyStrings(item.review.evidence), "FINAL_REVIEW_REQUIRED", "工作项最终 Code Review 尚未通过。" );
424:    const independentRequired = plan?.reviewBatches?.some((batch) => batch.independentRequired) || false;
425:    invariant(!independentRequired || item.review.independent, "INDEPENDENT_REVIEW_REQUIRED", "高风险批次需要独立复核证据。" );
426:    if (!(item.status === "DONE" && !item.integrityVersion)) {
427:      const snapshot = item.status === "DONE" ? await loadSnapshot(root, item.delivery?.source) : await sourceSnapshot(root);
428:      await assertVerification(root, item, plan, { snapshot });
429:      invariant(item.review.source?.digest === snapshot.digest, "STALE_REVIEW", "审查结论不对应当前待交付代码。" );
430:    }
431:    return;
432:  }
433:  if (target === "DONE") {
434:    invariant(item.acceptance.status === "pass" && nonEmptyStrings(item.acceptance.evidence), "ACCEPTANCE_REQUIRED", "DONE 前缺少有权验收证据。" );
435:    if (!(item.status === "DONE" && !item.integrityVersion)) {
436:      const snapshot = item.status === "DONE" ? await loadSnapshot(root, item.delivery?.source) : await sourceSnapshot(root);
437:      await assertVerification(root, item, plan, { snapshot });
438:      invariant(item.review.source?.digest === snapshot.digest && item.acceptance.source?.digest === snapshot.digest, "STALE_ACCEPTANCE", "验收和审查必须对应同一待交付代码版本。" );
439:    }
440:    return;
441:  }
442:  if (target === "ANSWERED") {
443:    invariant(item.type === "ANALYSIS", "TYPE_MISMATCH", "只有 ANALYSIS 可以进入 ANSWERED。" );
444:    invariant(item.analysis.status === "pass", "ANALYSIS_INCOMPLETE", "分析回答尚未标记通过。" );
445:    invariant(item.analysis.conclusions.length > 0, "ANALYSIS_CONCLUSION_REQUIRED", "至少需要一个带状态的分析结论。" );
446:    for (const conclusion of item.analysis.conclusions) {
447:      invariant(CONCLUSION_STATUSES.includes(conclusion.status), "ANALYSIS_STATUS_INVALID", "分析结论状态无效。", { conclusion });
448:      invariant(conclusion.text?.trim(), "ANALYSIS_TEXT_REQUIRED", "分析结论不能为空。" );
449:      if (conclusion.status !== "UNKNOWN") {
450:        invariant(nonEmptyStrings(conclusion.evidence), "ANALYSIS_EVIDENCE_REQUIRED", `${conclusion.status} 结论缺少证据。`);
451:      }
452:    }
453:  }
454:}
