456:export function collectHistoryErrors(item) {
457:  const errors = [];
458:  if (!Array.isArray(item.history) || item.history.length === 0) return ["状态历史为空。"];
459:  let previous = null;
460:  for (let index = 0; index < item.history.length; index += 1) {
461:    const entry = item.history[index];
462:    if (entry.from !== previous) errors.push(`history[${index}] from 与前一状态不一致。`);
463:    if (!WORK_STATUSES.includes(entry.to)) errors.push(`history[${index}] 目标状态无效。`);
464:    if (entry.to !== "BLOCKED" && entry.from !== "BLOCKED" && entry.from !== null) {
465:      const allowed = BASE_TRANSITIONS[item.type]?.[entry.from] || [];
466:      const recovery = ["reopen", "replan"].includes(entry.action) && entry.reason?.trim() && entry.revision > 1 &&
467:        ["IMPLEMENTING", "VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"].includes(entry.from) &&
468:        entry.to === (entry.action === "replan" ? "SOLUTION_DESIGN" : "IMPLEMENTING");
469:      if (!allowed.includes(entry.to) && !recovery) errors.push(`history[${index}] 包含非法转换 ${entry.from} -> ${entry.to}。`);
470:    }
471:    if (entry.to === "BLOCKED" && !entry.reason?.trim()) errors.push(`history[${index}] 阻塞缺少原因。`);
472:    if (entry.from === "BLOCKED" && entry.to !== entry.unblockedTo) errors.push(`history[${index}] 解除阻塞目标记录无效。`);
473:    previous = entry.to;
474:  }
475:  if (previous !== item.status) errors.push("当前状态与历史最后状态不一致。");
476:  return errors;
477:}
