479:export async function collectProgressErrors(root, item, plan, { allowStale = false } = {}) {
480:  const errors = [...collectWorkItemShapeErrors(item), ...collectHistoryErrors(item)];
481:  if (item.status === "BLOCKED") return [...new Set(errors)];
482:  const addGateError = async (target) => {
483:    try {
484:      await assertTransitionGates(root, item, plan, target);
485:    } catch (error) {
486:      if (allowStale && ["VERIFICATION_NOT_CURRENT", "STALE_VERIFICATION", "STALE_VERIFICATION_STAGE", "STALE_REVIEW", "STALE_ACCEPTANCE"].includes(error.code)) return;
487:      errors.push(`${target}: ${error.message}`);
488:      if (error.details?.errors) errors.push(...error.details.errors.map((detail) => `${target}: ${detail}`));
489:    }
490:  };
491:
492:  if (item.type === "ANALYSIS") {
493:    if (["ANALYZING", "ANSWERED"].includes(item.status)) await addGateError("ANALYZING");
494:    if (item.status === "ANSWERED") await addGateError("ANSWERED");
495:    return [...new Set(errors)];
496:  }
497:
498:  const reached = (statuses) => statuses.includes(item.status);
499:  if (reached(["SOLUTION_DESIGN", "DATABASE_DESIGN", "PLANNED", "IMPLEMENTING", "VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) {
500:    await addGateError("SOLUTION_DESIGN");
501:  }
502:  if (reached(["PLANNED", "IMPLEMENTING", "VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) {
503:    await addGateError("PLANNED");
504:  }
505:  if (reached(["IMPLEMENTING", "VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) await addGateError("IMPLEMENTING");
506:  if (reached(["VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) await addGateError("VERIFYING");
507:  if (reached(["CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) await addGateError("CODE_REVIEW");
508:  if (reached(["READY_FOR_ACCEPTANCE", "DONE"])) await addGateError("READY_FOR_ACCEPTANCE");
509:  if (item.status === "DONE") await addGateError("DONE");
510:  return [...new Set(errors)];
511:}
