306:      const current = await sourceSnapshot(root);
307:      const delivery = await prepareDelivery(root, item, plan, current);
308:      const baseline = await saveSnapshot(root, paths.directory, delivery.baseline);
309:      item.integrityVersion = 1;
310:      item.revision ||= 1;
311:      item.delivery = { source: await saveSnapshot(root, paths.directory, current), baseline, baselineAt: delivery.baselineAt, ownedChanges: delivery.ownedChanges, planDigest: planDigest(item, plan), at: nowIso(), head: (await getGitBaseline(root)).commit };
312:    }
313:    if (target === "BLOCKED") {
314:      item.blocked = { from, reason, at: nowIso() };
315:    } else if (from === "BLOCKED") {
316:      item.blocked = null;
317:    }
318:    item.status = target;
319:    item.updatedAt = nowIso();
320:    item.history.push({
321:      from,
322:      to: target,
323:      at: item.updatedAt,
324:      reason: target === "BLOCKED" ? reason : from === "BLOCKED" ? "unblocked" : reason || "gate-passed",
325:      ...(from === "BLOCKED" ? { unblockedTo: target } : {}),
326:    });
327:    assertValidWorkItem(item);
