1:export function createToolTiming() {
2:  const tools = new Map();
3:  const unmatchedEnds = new Set();
4:  return {
5:    start(id, at) {
6:      if (typeof id === "string" && !tools.has(id)) tools.set(id, { id, startMs: at, endMs: null });
7:    },
8:    end(id, at) {
9:      if (typeof id !== "string") return;
10:      const entry = tools.get(id);
11:      if (entry && entry.endMs === null) entry.endMs = Math.max(entry.startMs, at);
12:      else if (!entry) unmatchedEnds.add(id);
13:    },
14:    summarize(durationMs) {
15:      const spans = [...tools.values()].map(entry => ({ ...entry, endMs: entry.endMs ?? durationMs, complete: entry.endMs !== null }));
16:      const sorted = spans.toSorted((a,b) => a.startMs-b.startMs);
17:      let toolActiveMs = 0, end = 0;
18:      for (const span of sorted) {
19:        const right = Math.min(durationMs, span.endMs);
20:        toolActiveMs += Math.max(0, right - Math.max(end, span.startMs));
21:        end = Math.max(end, right);
22:      }
23:      return { basis: "local-event-receive-time", toolActiveMs, otherElapsedMs: Math.max(0, durationMs-toolActiveMs), spans, unmatchedCompletions: [...unmatchedEnds],
24:        limitation: "工具区间按接收事件估计并合并重叠；其余耗时包含模型、网络、客户端启动和收尾，不等于纯推理耗时。" };
25:    },
26:  };
27:}

